import cv2,numpy as np
from PIL import Image
im=np.array(Image.open('first_frame.png').convert('RGB')).astype(int)
# Find local maxima in a cube-likelihood: compact neutral region with square-ish aspect and dark border.
# Score windows using chroma low relative to surrounding ring, inside variance moderate, and rectangle edge contrast.
R,G,B=im.transpose(2,0,1); C=R-B; L=(R+G+B)/3
scores=[]
for s in range(12,34,2):
 for y in range(0,144-s):
  for x in range(0,256-s):
   c=C[y:y+s,x:x+s]; l=L[y:y+s,x:x+s]
   inner=np.mean(np.clip((42-c)/20,0,1))*0.8 + (np.mean(l)-120)/100
   # border ring
   ring=[]
   if y>2: ring.append(C[y-2,x:x+s]); ring.append(L[y-2,x:x+s])
   if y+s+2<144: ring.append(C[y+s+1,x:x+s]); ring.append(L[y+s+1,x:x+s])
   if x>2: ring.append(C[y:y+s,x-2]); ring.append(L[y:y+s,x-2])
   if x+s+2<256: ring.append(C[y:y+s,x+s+1]); ring.append(L[y:y+s,x+s+1])
   cc=np.concatenate([z for z in ring if z.ndim==1])
   # contrast low chroma inside vs ring
   contrast=np.mean(np.clip((C[y:y+s,x:x+s]-C[y-2,x:x+s].mean() if y>2 else 0),-50,50))
   scores.append((inner,x,y,s,c.mean(),l.mean(),contrast))
for z in sorted(scores,reverse=True)[:30]: print('score %.3f xy %d,%d s%d chroma %.1f lum %.1f contrast %.1f'%z)
